module gondola_scheduler (input [7:0] arrival_times_0, input [7:0] arrival_times_1, input [7:0] arrival_times_2, input [7:0] arrival_times_3, input [7:0] arrival_times_4, input [7:0] arrival_times_5, input [7:0] arrival_times_6, input [7:0] arrival_times_7, input [4:0] valid_skiers, input [4:0] T, input [2:0] G, output [15:0] total_waiting_time);wire [6:0] dep_interval;assign dep_interval = (2*T + G - 1) / G;wire [7:0] arr0 = arrival_times_0;wire [15:0] wait0;assign wait0 = (valid_skiers & 1) ? ((unsigned(arr0) + dep_interval -1) / dep_interval * dep_interval - unsigned(arr0)) : 16'd0;wire [7:0] arr1 = arrival_times_1;wire [15:0] wait1;assign wait1 = (valid_skiers & 2) ? ((unsigned(arr1) + dep_interval -1) / dep_interval * dep_interval - unsigned(arr1)) : 16'd0;wire [7:0] arr2 = arrival_times_2;wire [15:0] wait2;assign wait2 = (valid_skiers & 4) ? ((unsigned(arr2) + dep_interval -1) / dep_interval * dep_interval - unsigned(arr2)) : 16'd0;wire [7:0] arr3 = arrival_times_3;wire [15:0] wait3;assign wait3 = (valid_skiers & 8) ? ((unsigned(arr3) + dep_interval -1) / dep_interval * dep_interval - unsigned(arr3)) : 16'd0;wire [7:0] arr4 = arrival_times_4;wire [15:0] wait4;assign wait4 = (valid_skiers & 16) ? ((unsigned(arr4) + dep_interval -1) / dep_interval * dep_interval - unsigned(arr4)) : 16'd0;wire [15:0] total;assign total = wait0 + wait1 + wait2 + wait3 + wait4;assign total_waiting_time = total;endmodule